    for _ in range(m):
        l,r=map(int,d[pos:pos+2]); pos+=2; diff[l]+=1; diff[r+1]-=1
    pairs=[]; count=0
    for i,v in enumerate(a):
        count+=diff[i]; pairs.append((v,count))
    pairs.sort(); values=[v for v,c in pairs]; prefix=[0]
    for v,c in pairs: prefix.append(prefix[-1]+c)
